python - <<'PY'
import json,numpy as np
from PIL import Image
from scipy.ndimage import convolve
spec=json.load(open('/app/output/spec.json')); wells=spec['static']['wells']['wells']; pal=np.array([np.array(w['rgb'])*255 for w in wells],np.float32)
im=np.array(Image.open('/app/target.png').convert('RGB'),np.float32)
small=im.reshape(64,16,64,16,3).mean((1,3)); labels=((small[:,:,None,:]-pal[None,None,:,:])**2).sum(3).argmin(2)
votes=np.stack([convolve((labels==c).astype(float),np.ones((3,3)),mode='nearest') for c in range(10)],2); labels=votes.argmax(2)
h=4;cands=[]
for r in range(65-h):
 eq=np.all(labels[r:r+h]==labels[r],axis=0)
 for color in range(10):
  ix=np.flatnonzero(eq & (labels[r]==color))
  if len(ix):
   st=pr=ix[0]
   for col in list(ix[1:])+[None]:
    if col is None or col>pr+1:
     b=pr+1
     if b-st>=8:cands.append({'area':h*(b-st),'r':int(r),'a':int(st),'b':int(b),'c':color,'h':h})
     if col is not None:st=col
    if col is not None:pr=col
cands.sort(key=lambda x:x['area'],reverse=True)
selected=[]
for c in cands:
 overlap=False
 for s in selected:
  area=max(0,min(c['r']+h,s['r']+h)-max(c['r'],s['r']))*max(0,min(c['b'],s['b'])-max(c['a'],s['a']))
  if area>0: overlap=True;break
 if not overlap:selected.append(c)
 if len(selected)>=13:break
print('cands',len(cands),'selected',len(selected))
for s in selected: print(s,'paint',wells[s['c']]['name'],'rect mm',round(s['area']*227.185**2/64**2))
PY

